package live.linghe.privateinput;
import android.provider.*;import android.database.*;import android.os.*;import java.io.*;import java.util.*;

/** Signature-protected document provider containing this test APK's synthetic session only. */
public final class FixtureDocuments extends DocumentsProvider {
 private static final String[] ROOTS={DocumentsContract.Root.COLUMN_ROOT_ID,DocumentsContract.Root.COLUMN_DOCUMENT_ID,DocumentsContract.Root.COLUMN_TITLE,DocumentsContract.Root.COLUMN_FLAGS,DocumentsContract.Root.COLUMN_MIME_TYPES};
 private static final String[] DOCS={DocumentsContract.Document.COLUMN_DOCUMENT_ID,DocumentsContract.Document.COLUMN_DISPLAY_NAME,DocumentsContract.Document.COLUMN_MIME_TYPE,DocumentsContract.Document.COLUMN_FLAGS,DocumentsContract.Document.COLUMN_SIZE,DocumentsContract.Document.COLUMN_LAST_MODIFIED};
 public boolean onCreate(){return true;}
 private File root(String session)throws FileNotFoundException {try{String id=UUID.fromString(session).toString();File root=new File(getContext().getCacheDir(),"lexicon-acceptance-"+id);if(!new File(root,"fixture-owned-v1").isFile())throw new FileNotFoundException();return root;}catch(IllegalArgumentException invalid){throw new FileNotFoundException();}}
 private String[] parts(String document)throws FileNotFoundException{String[] parts=document.split("\\|",-1);if(parts.length!=2||(!parts[1].equals("root")&&!parts[1].equals("import.json")&&!parts[1].matches("out-[0-9a-f-]{36}\\.json")))throw new FileNotFoundException();root(parts[0]);return parts;}
 private File file(String document)throws FileNotFoundException{String[] id=parts(document);return id[1].equals("root")?new File(root(id[0]),"documents"):new File(new File(root(id[0]),"documents"),id[1]);}
 public Cursor queryRoots(String[] projection)throws FileNotFoundException {
  String[] columns=projection==null?ROOTS:projection;MatrixCursor cursor=new MatrixCursor(columns);String session=getContext().getSharedPreferences("document-harness",0).getString("fixture",null);if(session==null)return cursor;root(session);Object[] row=new Object[columns.length];for(int i=0;i<columns.length;i++){String key=columns[i];if(key.equals(DocumentsContract.Root.COLUMN_ROOT_ID))row[i]=session;else if(key.equals(DocumentsContract.Root.COLUMN_DOCUMENT_ID))row[i]=session+"|root";else if(key.equals(DocumentsContract.Root.COLUMN_TITLE))row[i]="灵鹤合成验收";else if(key.equals(DocumentsContract.Root.COLUMN_FLAGS))row[i]=DocumentsContract.Root.FLAG_SUPPORTS_CREATE|DocumentsContract.Root.FLAG_LOCAL_ONLY;else if(key.equals(DocumentsContract.Root.COLUMN_MIME_TYPES))row[i]="application/json";}cursor.addRow(row);return cursor;
 }
 private void add(MatrixCursor cursor,String document)throws FileNotFoundException{
  String[] id=parts(document);File file=file(document);if(!file.exists())throw new FileNotFoundException();boolean directory=id[1].equals("root");String name=directory?"灵鹤合成验收":id[1].equals("import.json")?"导入合成词库.json":getContext().getSharedPreferences("document-names-"+id[0],0).getString(id[1],"导出.json");Object[] row=new Object[cursor.getColumnCount()];String[] columns=cursor.getColumnNames();for(int i=0;i<columns.length;i++){String key=columns[i];if(key.equals(DocumentsContract.Document.COLUMN_DOCUMENT_ID))row[i]=document;else if(key.equals(DocumentsContract.Document.COLUMN_DISPLAY_NAME))row[i]=name;else if(key.equals(DocumentsContract.Document.COLUMN_MIME_TYPE))row[i]=directory?DocumentsContract.Document.MIME_TYPE_DIR:"application/json";else if(key.equals(DocumentsContract.Document.COLUMN_FLAGS))row[i]=directory?DocumentsContract.Document.FLAG_DIR_SUPPORTS_CREATE:id[1].equals("import.json")?0:DocumentsContract.Document.FLAG_SUPPORTS_WRITE;else if(key.equals(DocumentsContract.Document.COLUMN_SIZE))row[i]=directory?0:file.length();else if(key.equals(DocumentsContract.Document.COLUMN_LAST_MODIFIED))row[i]=file.lastModified();}cursor.addRow(row);
 }
 public Cursor queryDocument(String document,String[] projection)throws FileNotFoundException{MatrixCursor cursor=new MatrixCursor(projection==null?DOCS:projection);add(cursor,document);return cursor;}
 public Cursor queryChildDocuments(String parent,String[] projection,String order)throws FileNotFoundException{String[] id=parts(parent);if(!id[1].equals("root"))throw new FileNotFoundException();MatrixCursor cursor=new MatrixCursor(projection==null?DOCS:projection);File[] files=file(parent).listFiles();if(files!=null){Arrays.sort(files);for(File child:files)if(child.isFile()&&(child.getName().equals("import.json")||child.getName().matches("out-[0-9a-f-]{36}\\.json")))add(cursor,id[0]+"|"+child.getName());}return cursor;}
 public ParcelFileDescriptor openDocument(String document,String mode,CancellationSignal signal)throws FileNotFoundException{String[] id=parts(document);if(id[1].equals("root")||(id[1].equals("import.json")&&mode.contains("w")))throw new FileNotFoundException();return ParcelFileDescriptor.open(file(document),ParcelFileDescriptor.parseMode(mode));}
 public String createDocument(String parent,String mime,String name)throws FileNotFoundException{String[] id=parts(parent);if(!id[1].equals("root")||!mime.equals("application/json"))throw new FileNotFoundException();String output="out-"+UUID.randomUUID()+".json";File file=new File(file(parent),output);try{if(!file.createNewFile())throw new IOException();getContext().getSharedPreferences("document-names-"+id[0],0).edit().putString(output,name).commit();}catch(IOException failure){throw new FileNotFoundException();}return id[0]+"|"+output;}
 @Override public boolean isChildDocument(String parent,String child){try{String[] a=parts(parent),b=parts(child);return a[0].equals(b[0])&&a[1].equals("root")&&!b[1].equals("root");}catch(Exception invalid){return false;}}
}
